
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_cqtp25_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cqtp25", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-2.103550686539588e+00, -2.062585404914594e+00, -2.005193477876806e+00, -1.925711487630528e+00, -1.817444098831194e+00, -1.673407335757947e+00, -1.488071905189792e+00, -1.260383478419284e+00, -9.973395541486580e-01, -7.147876689943149e-01, -4.390625887514427e-01, -2.836158554059602e-01, -2.389913394575462e-01, -1.829947822254294e-01, -1.078786206213054e-01, -3.968556533792288e-02, -7.555309844846973e-03, -3.953108227135818e-03, -9.819497836493084e-04, -1.323371882126093e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


